1	// Shared black-box harness: spawn `node server.mjs` and talk to it over HTTP or raw TCP.
2	import assert from 'node:assert/strict';
3	import { spawn } from 'node:child_process';
4	import http from 'node:http';
5	import net from 'node:net';
6	import fs from 'node:fs';
7	import os from 'node:os';
8	import path from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	
11	export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
12	export const SERVER = path.join(ROOT, 'server.mjs');
13	export const JSON_TYPE = 'application/json; charset=utf-8';
14	export const JSON_HEADERS = Object.freeze({ 'content-type': 'application/json' });
15	export const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
16	const EXIT_TIMEOUT_MS = 10000;
17	
18	/** Fresh temp folder, removed after the test. */
19	export function makeTmp(t) {
20	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'booking-h-'));
21	  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
22	  return dir;
23	}
24	
25	/**
26	 * Spawns the server. `env` entries override the defaults (PORT=0, DATA_FILE=<dir>/data.json);
27	 * an entry whose value is `undefined` removes that variable entirely.
28	 */
29	export function spawnServer(dir, { env = {}, cwd } = {}) {
30	  const merged = { ...process.env, PORT: '0', DATA_FILE: path.join(dir, 'data.json'), ...env };
31	  const fullEnv = Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
32	  return spawn(process.execPath, [SERVER], { env: fullEnv, cwd: cwd ?? dir });
33	}
34	
35	/**
36	 * Starts the server and resolves once it prints the listening line.
37	 * `out()` / `err()` return everything written to stdout / stderr so far.
38	 */
39	export function startServer(t, dir, opts = {}) {
40	  const child = spawnServer(dir, opts);
41	  t.after(() => child.kill('SIGKILL'));
42	  let stdout = '';
43	  let stderr = '';
44	  child.stdout.on('data', (d) => { stdout += d; });
45	  child.stderr.on('data', (d) => { stderr += d; });
46	  return new Promise((resolve, reject) => {
47	    const onData = () => {
48	      const m = LISTEN_RE.exec(stdout);
49	      if (!m) return;
50	      child.stdout.off('data', onData);
51	      child.off('exit', onExit);
52	      resolve({ port: Number(m[1]), child, out: () => stdout, err: () => stderr });
53	    };
54	    const onExit = (code) => reject(new Error(`exited ${code} before listening: ${stderr}`));
55	    child.stdout.on('data', onData);
56	    child.on('exit', onExit);
57	  });
58	}
59	
60	/** Spawns the server in a fresh temp dir; returns { dir, port, child, out, err }. */
61	export async function boot(t, opts = {}) {
62	  const dir = makeTmp(t);
63	  const srv = await startServer(t, dir, opts);
64	  return { dir, ...srv };
65	}
66	
67	/**
68	 * Runs the server until it exits; resolves { code, stdout, stderr }.
69	 * When it is still running after the timeout it is killed and `code` is 'still running',
70	 * so the caller's own assertion (with its case label) reports the failure.
71	 */
72	export function runToExit(t, dir, opts = {}) {
73	  const child = spawnServer(dir, opts);
74	  t.after(() => child.kill('SIGKILL'));
75	  return new Promise((resolve) => {
76	    let stdout = '';
77	    let stderr = '';
78	    const timer = setTimeout(() => {
79	      child.removeAllListeners('close');
80	      child.kill('SIGKILL');
81	      resolve({ code: 'still running', stdout, stderr });
82	    }, EXIT_TIMEOUT_MS);
83	    child.stdout.on('data', (d) => { stdout += d; });
84	    child.stderr.on('data', (d) => { stderr += d; });
85	    // 'close' (not 'exit') fires only after stdout and stderr are fully read.
86	    child.on('close', (code) => {
87	      clearTimeout(timer);
88	      resolve({ code, stdout, stderr });
89	    });
90	  });
91	}
92	
93	/** HTTP request; resolves { status, headers, text, json } (json undefined when not JSON). */
94	export function request(port, method, reqPath, { headers = {}, body } = {}) {
95	  return new Promise((resolve, reject) => {
96	    const opts = { host: '127.0.0.1', port, method, path: reqPath, headers, agent: false };
97	    const req = http.request(opts, (res) => {
98	      const chunks = [];
99	      res.on('data', (c) => chunks.push(c));
100	      res.on('end', () => {
101	        const text = Buffer.concat(chunks).toString('utf8');
102	        let json;
103	        try { json = JSON.parse(text); } catch { json = undefined; }
104	        resolve({ status: res.statusCode, headers: res.headers, text, json });
105	      });
106	    });
107	    req.on('error', reject);
108	    req.end(body);
109	  });
110	}
111	
112	/** POST /api/bookings; objects are JSON-encoded, strings and Buffers are sent as is. */
113	export function post(port, obj, headers = JSON_HEADERS) {
114	  const body = typeof obj === 'string' || Buffer.isBuffer(obj) ? obj : JSON.stringify(obj);
115	  return request(port, 'POST', '/api/bookings', { headers, body });
116	}
117	
118	/**
119	 * Sends raw bytes over TCP and resolves the parsed status line, lower-cased headers and body text.
120	 * Use for request lines or headers that node:http would refuse to send. Send `Connection: close`:
121	 * the socket is not half-closed (node:http aborts a request whose client sent FIN), so the reply
122	 * ends when the server closes the connection.
123	 */
124	export function rawRequest(port, raw) {
125	  return new Promise((resolve, reject) => {
126	    const socket = net.connect(port, '127.0.0.1', () => socket.write(raw));
127	    const chunks = [];
128	    socket.on('data', (c) => chunks.push(c));
129	    socket.on('error', reject);
130	    socket.on('end', () => {
131	      const text = Buffer.concat(chunks).toString('utf8');
132	      const split = text.indexOf('\r\n\r\n');
133	      const head = split === -1 ? text : text.slice(0, split);
134	      const bodyText = split === -1 ? '' : text.slice(split + 4);
135	      const [statusLine, ...headerLines] = head.split('\r\n');
136	      const headers = Object.fromEntries(headerLines.map((l) => {
137	        const i = l.indexOf(':');
138	        return [l.slice(0, i).trim().toLowerCase(), l.slice(i + 1).trim()];
139	      }));
140	      let json;
141	      try { json = JSON.parse(bodyText); } catch { json = undefined; }
142	      resolve({ status: Number(statusLine.split(' ')[1]), headers, text: bodyText, json });
143	    });
144	  });
145	}
146	
147	/** A valid booking body; `over` replaces fields. */
148	export const valid = (over = {}) => ({
149	  room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '10:00', end: '11:00', ...over,
150	});
151	
152	/** Asserts status, exact `{error}` body and the JSON content type. */
153	export function assertError(res, status, message) {
154	  assert.equal(res.status, status);
155	  assert.deepEqual(res.json, { error: message });
156	  assert.equal(res.headers['content-type'], JSON_TYPE);
157	}
158	
159	/** Resolves true when 127.0.0.1:<port> can be bound right now. */
160	export function portIsFree(port) {
161	  return new Promise((resolve) => {
162	    const probe = net.createServer();
163	    probe.once('error', () => resolve(false));
164	    probe.listen(port, '127.0.0.1', () => probe.close(() => resolve(true)));
165	  });
166	}
