1	// Black-box smoke tests: spawn `node server.mjs` and talk to it over HTTP.
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { spawn } from 'node:child_process';
5	import http from 'node:http';
6	import net from 'node:net';
7	import fs from 'node:fs';
8	import os from 'node:os';
9	import path from 'node:path';
10	import { fileURLToPath } from 'node:url';
11	
12	const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
13	const SERVER = path.join(ROOT, 'server.mjs');
14	const JSON_TYPE = 'application/json; charset=utf-8';
15	const JSON_HEADERS = { 'content-type': 'application/json' };
16	const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
17	
18	function makeTmp(t) {
19	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'booking-'));
20	  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
21	  return dir;
22	}
23	
24	function spawnServer({ env = {}, cwd }, dir) {
25	  const fullEnv = { ...process.env, PORT: '0', DATA_FILE: path.join(dir, 'data.json'), ...env };
26	  return spawn(process.execPath, [SERVER], { env: fullEnv, cwd: cwd ?? dir });
27	}
28	
29	function startServer(t, dir, opts = {}) {
30	  const child = spawnServer(opts, dir);
31	  t.after(() => child.kill('SIGKILL'));
32	  return new Promise((resolve, reject) => {
33	    let out = '';
34	    let err = '';
35	    child.stderr.on('data', (d) => { err += d; });
36	    child.stdout.on('data', (d) => {
37	      out += d;
38	      const m = LISTEN_RE.exec(out);
39	      if (m) resolve({ port: Number(m[1]), child, stdout: out });
40	    });
41	    child.on('exit', (code) => reject(new Error(`exited ${code} before listening: ${err}`)));
42	  });
43	}
44	
45	function runToExit(t, dir, opts = {}) {
46	  const child = spawnServer(opts, dir);
47	  t.after(() => child.kill('SIGKILL'));
48	  return new Promise((resolve, reject) => {
49	    let stdout = '';
50	    let stderr = '';
51	    const timer = setTimeout(() => reject(new Error('server did not exit in 5s')), 5000);
52	    child.stdout.on('data', (d) => { stdout += d; });
53	    child.stderr.on('data', (d) => { stderr += d; });
54	    child.on('close', (code) => { // after stdio is drained, unlike 'exit'
55	      clearTimeout(timer);
56	      resolve({ code, stdout, stderr });
57	    });
58	  });
59	}
60	
61	function request(port, method, reqPath, { headers = {}, body } = {}) {
62	  return new Promise((resolve, reject) => {
63	    const req = http.request({ host: '127.0.0.1', port, method, path: reqPath, headers, agent: false }, (res) => {
64	      const chunks = [];
65	      res.on('data', (c) => chunks.push(c));
66	      res.on('end', () => {
67	        const text = Buffer.concat(chunks).toString('utf8');
68	        let json;
69	        try { json = JSON.parse(text); } catch { json = undefined; }
70	        resolve({ status: res.statusCode, headers: res.headers, text, json });
71	      });
72	    });
73	    req.on('error', reject);
74	    req.end(body);
75	  });
76	}
