1	import vm from 'node:vm';
2	import fs from 'node:fs';
3	
4	const IDS = ['booking-form', 'room', 'title', 'date', 'start', 'end', 'book',
5	  'filter-date', 'show-all', 'booking-list', 'error'];
6	
7	function toNode(n) {
8	  return typeof n === 'string' ? { nodeType: 3, textContent: n } : n;
9	}
10	
11	export class FakeElement {
12	  constructor(tagName, id = '') {
13	    this.tagName = tagName;
14	    this.id = id;
15	    this.children = [];
16	    this.value = '';
17	    this.type = '';
18	    this.disabled = false;
19	    this.listeners = new Map();
20	  }
21	
22	  get textContent() {
23	    return this.children.map((c) => c.textContent).join('');
24	  }
25	
26	  set textContent(s) {
27	    if (this.onTextSet) this.onTextSet(s);
28	    this.children = s === '' ? [] : [toNode(String(s))];
29	  }
30	
31	  append(...nodes) {
32	    this.children = [...this.children, ...nodes.map(toNode)];
33	  }
34	
35	  replaceChildren(...nodes) {
36	    this.children = nodes.map(toNode);
37	  }
38	
39	  addEventListener(type, fn) {
40	    this.listeners.set(type, [...(this.listeners.get(type) ?? []), fn]);
41	  }
42	
43	  dispatch(type) {
44	    const event = { preventDefault() { this.defaultPrevented = true; }, defaultPrevented: false };
45	    for (const fn of this.listeners.get(type) ?? []) fn(event);
46	    return event;
47	  }
48	}
49	
50	export function deferred() {
51	  let resolve;
52	  let reject;
53	  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
54	  return { promise, resolve, reject };
55	}
56	
57	export function makeReply(status, body, { badJson = false } = {}) {
58	  const reply = {
59	    status,
60	    jsonCalls: 0,
61	    json() {
62	      reply.jsonCalls += 1;
63	      return badJson ? Promise.reject(new SyntaxError('bad json')) : Promise.resolve(body);
64	    },
65	  };
66	  return reply;
67	}
68	
69	export async function flush() {
70	  for (let i = 0; i < 5; i += 1) await new Promise((r) => setImmediate(r));
71	}
72	
73	export function loadPage(appPath) {
74	  const els = Object.fromEntries(IDS.map((id) => [id, new FakeElement('x', id)]));
75	  const calls = [];
76	  const document = {
77	    getElementById: (id) => els[id],
78	    createElement: (tag) => new FakeElement(tag),
79	  };
80	  const fetch = (url, options) => {
81	    const d = deferred();
82	    calls.push({ url, options, bookDisabled: els.book.disabled, reply: (r) => d.resolve(r), fail: (e) => d.reject(e ?? new TypeError('down')) });
83	    return d.promise;
84	  };
85	  const context = vm.createContext({ document, fetch });
86	  vm.runInContext(fs.readFileSync(appPath, 'utf8'), context, { filename: 'app.js' });
87	  return { els, calls };
88	}
